mapper.select:
SELECT DISTINCT
    gu.upload_id, gu.answer_id, gu.binding_id, gu.source_sheet_id, gu.student_id,
    gu.question_name, gu.file_name, gu.file_size, gu.mime_type,
    gu.teacher_machine_ip, gu.stored_path, gu.access_url, gu.client_upload_id, gu.upload_time
FROM biz_guide_sheet_upload gu
INNER JOIN biz_guide_sheet_progress p
        ON p.binding_id = gu.binding_id
       AND p.student_id = gu.student_id
WHERE gu.binding_id = #{bindingId}
  AND p.dept_id = #{deptId}
  AND p.entry_year = #{entryYear}
  AND p.class_code = #{classCode}
ORDER BY gu.upload_time DESC, gu.upload_id DESC

SELECT 
FROM biz_guide_sheet_upload
WHERE binding_id = #{bindingId}
  AND student_id = #{studentId}
  AND client_upload_id = #{clientUploadId}
LIMIT 1

